"""Exact finite group generated by the signed exchanges of adjacent roots."""
from itertools import permutations, product
from pathlib import Path
import json

# Entry j is the signed image of e_(j+1); entries are never zero.
identity=(1,2,3,4)
def compose(g,h):
    return tuple((1 if x>0 else -1)*g[abs(x)-1] for x in h)
def parity(p):
    return -1 if sum(p[j]>p[k] for j in range(4) for k in range(j+1,4))%2 else 1
gens=[]
for j in range(3):
    g=list(identity);g[j]=j+2;g[j+1]=-(j+1);gens.append(tuple(g))
group={identity};todo=[identity]
while todo:
    g=todo.pop()
    for h in gens:
        v=compose(g,h)
        if v not in group: group.add(v);todo.append(v)
all_signed={tuple(si*(pi+1) for si,pi in zip(signs,perm))
            for perm in permutations(range(4)) for signs in product([-1,1],repeat=4)
            if parity(perm)*__import__('math').prod(signs)==1}
assert group==all_signed and len(group)==192
pure={g for g in group if tuple(map(abs,g))==identity}
assert len(pure)==8
orbit={g[0] for g in group}
assert orbit==set([-4,-3,-2,-1,1,2,3,4])
stabilizer={g for g in group if g[0]==1}
fixed=[v for v in [-4,-3,-2,-1,1,2,3,4]
       if all((1 if v>0 else -1)*g[abs(v)-1]==v for g in stabilizer)]
assert fixed==[-1,1]
assert all(compose(g,(-1,-2,-3,-4))==compose((-1,-2,-3,-4),g) for g in group)
out={'generators':gens,'generated_order':len(group),'equals_determinant_one_signed_group':True,
     'pure_sign_kernel_order':len(pure),'orbit_size':len(orbit),
     'point_stabilizer_order':len(stabilizer),'point_stabilizer_fixed_states':fixed,
     'simultaneous_sign_is_central':True,
     'scope':'Finite permutation calculation; topological monodromy realization requires the accompanying proof.'}
Path(__file__).with_name('signed_root_group_exact.json').write_text(json.dumps(out,indent=2)+'\n',encoding='utf-8')
print(json.dumps(out,indent=2))
